// sync_fifo: parameterizable synchronous FIFO, first-word fall-through.
// Implements interface_spec.md per microarchitecture.md.
`timescale 1ns/1ps
`default_nettype none

module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam integer PW      = $clog2(DEPTH);
    localparam integer CW      = $clog2(DEPTH+1);
    localparam integer LAST_I  = DEPTH - 1;
    localparam [PW-1:0] LAST   = LAST_I[PW-1:0];
    localparam [CW-1:0] DEPTH_C = DEPTH[CW-1:0];
    localparam [CW-1:0] ZERO_C  = {CW{1'b0}};

    // Storage: datapath, not reset.
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    reg [PW-1:0] wr_ptr;
    reg [PW-1:0] rd_ptr;
    reg [CW-1:0] count_r;

    // Flags are compares on a register: no combinational input dependence.
    assign full  = (count_r == DEPTH_C);
    assign empty = (count_r == ZERO_C);
    assign count = count_r;

    // Flags gate the requests: overflow and underflow policy.
    wire wr_acc = wr_en && !full;
    wire rd_acc = rd_en && !empty;

    // First-word fall-through read port.
    assign rd_data = mem[rd_ptr];

    // Control: pointers and occupancy, synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr  <= {PW{1'b0}};
            rd_ptr  <= {PW{1'b0}};
            count_r <= ZERO_C;
        end else begin
            if (wr_acc) begin
                wr_ptr <= (wr_ptr == LAST) ? {PW{1'b0}} : wr_ptr + 1'b1;
            end
            if (rd_acc) begin
                rd_ptr <= (rd_ptr == LAST) ? {PW{1'b0}} : rd_ptr + 1'b1;
            end
            case ({wr_acc, rd_acc})
                2'b10:   count_r <= count_r + 1'b1;
                2'b01:   count_r <= count_r - 1'b1;
                default: count_r <= count_r;
            endcase
        end
    end

    // Storage write: only outside reset, only on an accepted write.
    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr] <= wr_data;
        end
    end

`ifdef FORMAL
    // Design-intent properties (microarchitecture.md section 6).
    reg f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    initial assume (!rst_n);

    always @(*) begin
        if (f_past_valid) begin
            assert (full  == (count_r == DEPTH_C));
            assert (empty == (count_r == ZERO_C));
            assert (!(full && empty));
            assert (count_r <= DEPTH_C);
            assert (wr_ptr <= LAST);
            assert (rd_ptr <= LAST);
            assert (wr_ptr == ((rd_ptr + count_r) % DEPTH));
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert (empty);
                assert (!full);
                assert (count_r == ZERO_C);
            end else begin
                case ({$past(wr_acc), $past(rd_acc)})
                    2'b10:   assert (count_r == $past(count_r) + 1'b1);
                    2'b01:   assert (count_r == $past(count_r) - 1'b1);
                    default: assert (count_r == $past(count_r));
                endcase
                if ($past(wr_en) && $past(full))
                    assert (wr_ptr == $past(wr_ptr));
                if ($past(rd_en) && $past(empty))
                    assert (rd_ptr == $past(rd_ptr));
            end
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
