// sync_fifo_tb: self-checking testbench for sync_fifo.
// Two FIFOs (DEPTH 8 x WIDTH 8, DEPTH 5 x WIDTH 12) on the same stimulus,
// each checked every cycle against a reference queue.
`timescale 1ns/1ps
`default_nettype none

module fifo_checker #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    input  wire                       rd_en,
    input  wire                       full,
    input  wire                       empty,
    input  wire [WIDTH-1:0]           rd_data,
    input  wire [$clog2(DEPTH+1)-1:0] count,
    input  wire                       done,
    output wire [31:0]                passed_o,
    output wire [31:0]                failed_o
);

    localparam integer PW     = $clog2(DEPTH);
    localparam integer CW     = $clog2(DEPTH+1);
    localparam integer LAST_I = DEPTH - 1;
    localparam [PW-1:0] LAST  = LAST_I[PW-1:0];
    localparam [CW-1:0] FULL_N = DEPTH[CW-1:0];
    localparam [CW-1:0] ZERO_N = {CW{1'b0}};

    // Reference queue.
    reg [WIDTH-1:0] q [0:DEPTH-1];
    reg [PW-1:0] head = {PW{1'b0}};
    reg [PW-1:0] tail = {PW{1'b0}};
    reg [CW-1:0] n    = {CW{1'b0}};
    reg started = 1'b0;
    reg w;
    reg r;

    // Coverage counters.
    reg [31:0] cov_fill        = 32'd0;
    reg [31:0] cov_wr_full     = 32'd0;
    reg [31:0] cov_drain       = 32'd0;
    reg [31:0] cov_rd_empty    = 32'd0;
    reg [31:0] cov_wrrd_empty  = 32'd0;
    reg [31:0] cov_wrrd_full   = 32'd0;
    reg [31:0] cov_wrrd_mid    = 32'd0;
    reg [31:0] cov_wrap_wr     = 32'd0;
    reg [31:0] cov_wrap_rd     = 32'd0;
    reg [31:0] cov_rst_traffic = 32'd0;

    reg [31:0] passed = 32'd0;
    reg [31:0] failed = 32'd0;
    reg cov_done = 1'b0;

    assign passed_o = passed;
    assign failed_o = failed;

    task check(input ok, input [8*24-1:0] what);
        begin
            if (ok) begin
                passed = passed + 32'd1;
            end else begin
                failed = failed + 32'd1;
                $error("sync_fifo DEPTH=%0d WIDTH=%0d: check '%0s' failed at %0t",
                       DEPTH, WIDTH, what, $time);
            end
        end
    endtask

    // Reference model update on the same rising edge as the DUT.
    always @(posedge clk) begin
        if (!rst_n) begin
            if (started && (n != ZERO_N) && (wr_en || rd_en))
                cov_rst_traffic = cov_rst_traffic + 32'd1;
            head    = {PW{1'b0}};
            tail    = {PW{1'b0}};
            n       = ZERO_N;
            started = 1'b1;
        end else if (started) begin
            w = wr_en && (n != FULL_N);
            r = rd_en && (n != ZERO_N);
            if (wr_en && (n == FULL_N)) cov_wr_full  = cov_wr_full + 32'd1;
            if (rd_en && (n == ZERO_N)) cov_rd_empty = cov_rd_empty + 32'd1;
            if (wr_en && rd_en) begin
                if (n == ZERO_N)      cov_wrrd_empty = cov_wrrd_empty + 32'd1;
                else if (n == FULL_N) cov_wrrd_full  = cov_wrrd_full + 32'd1;
                else                  cov_wrrd_mid   = cov_wrrd_mid + 32'd1;
            end
            if (r) begin
                if (head == LAST) begin
                    head = {PW{1'b0}};
                    cov_wrap_rd = cov_wrap_rd + 32'd1;
                end else begin
                    head = head + 1'b1;
                end
            end
            if (w) begin
                q[tail] = wr_data;
                if (tail == LAST) begin
                    tail = {PW{1'b0}};
                    cov_wrap_wr = cov_wrap_wr + 32'd1;
                end else begin
                    tail = tail + 1'b1;
                end
            end
            case ({w, r})
                2'b10:   n = n + 1'b1;
                2'b01:   n = n - 1'b1;
                default: n = n;
            endcase
            if (w && !r && (n == FULL_N)) cov_fill  = cov_fill + 32'd1;
            if (r && !w && (n == ZERO_N)) cov_drain = cov_drain + 32'd1;
        end
    end

    // Every-cycle checks, mid-cycle while outputs are stable.
    always @(negedge clk) begin
        if (started) begin
            check(full  == (n == FULL_N), "full");
            check(empty == (n == ZERO_N), "empty");
            check(count == n,             "count");
            if (n != ZERO_N)
                check(rd_data == q[head], "rd_data");
        end
        if (done && !cov_done) begin
            cov_done = 1'b1;
            check(cov_fill        != 32'd0, "cov fill to full");
            check(cov_wr_full     != 32'd0, "cov write while full");
            check(cov_drain       != 32'd0, "cov drain to empty");
            check(cov_rd_empty    != 32'd0, "cov read while empty");
            check(cov_wrrd_empty  != 32'd0, "cov wr+rd when empty");
            check(cov_wrrd_full   != 32'd0, "cov wr+rd when full");
            check(cov_wrrd_mid    != 32'd0, "cov wr+rd in between");
            check(cov_wrap_wr     != 32'd0, "cov write ptr wrap");
            check(cov_wrap_rd     != 32'd0, "cov read ptr wrap");
            check(cov_rst_traffic != 32'd0, "cov reset in traffic");
        end
    end

endmodule

module sync_fifo_tb;

    reg        clk     = 1'b0;
    reg        rst_n   = 1'b0;
    reg        wr_en   = 1'b1;
    reg        rd_en   = 1'b1;
    reg [11:0] wr_data = 12'd0;
    reg        done    = 1'b0;

    integer    seed;
    reg [31:0] rnd;
    reg [31:0] passed;
    reg [31:0] failed;
    reg [8*64-1:0] nonce;

    always #5 clk = ~clk;

    wire        full_a, empty_a;
    wire [7:0]  rd_data_a;
    wire [3:0]  count_a;
    wire        full_b, empty_b;
    wire [11:0] rd_data_b;
    wire [2:0]  count_b;
    wire [31:0] pass_a, fail_a, pass_b, fail_b;

    sync_fifo #(.DEPTH(8), .WIDTH(8)) dut_a (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data[7:0]), .full(full_a),
        .rd_en(rd_en), .rd_data(rd_data_a), .empty(empty_a),
        .count(count_a)
    );

    sync_fifo #(.DEPTH(5), .WIDTH(12)) dut_b (
        .clk(clk), .rst_n(rst_n),
        .wr_en(wr_en), .wr_data(wr_data), .full(full_b),
        .rd_en(rd_en), .rd_data(rd_data_b), .empty(empty_b),
        .count(count_b)
    );

    fifo_checker #(.DEPTH(8), .WIDTH(8)) chk_a (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .wr_data(wr_data[7:0]),
        .rd_en(rd_en), .full(full_a), .empty(empty_a), .rd_data(rd_data_a),
        .count(count_a), .done(done), .passed_o(pass_a), .failed_o(fail_a)
    );

    fifo_checker #(.DEPTH(5), .WIDTH(12)) chk_b (
        .clk(clk), .rst_n(rst_n), .wr_en(wr_en), .wr_data(wr_data),
        .rd_en(rd_en), .full(full_b), .empty(empty_b), .rd_data(rd_data_b),
        .count(count_b), .done(done), .passed_o(pass_b), .failed_o(fail_b)
    );

    // Directed cycles: fixed enables, random data.
    task cycles(input we, input re, input integer num);
        integer k;
        begin
            for (k = 0; k < num; k = k + 1) begin
                @(negedge clk);
                rnd     = $random(seed);
                wr_en   = we;
                rd_en   = re;
                wr_data = rnd[11:0];
            end
        end
    endtask

    // Random traffic with request probabilities wr_th/256 and rd_th/256.
    task random_phase(input [7:0] wr_th, input [7:0] rd_th, input integer num);
        integer k;
        begin
            for (k = 0; k < num; k = k + 1) begin
                @(negedge clk);
                rnd     = $random(seed);
                wr_en   = (rnd[7:0]  < wr_th);
                rd_en   = (rnd[15:8] < rd_th);
                wr_data = rnd[27:16];
            end
        end
    endtask

    initial begin
        seed = 32'h5EEDF1F0;

        // Reset with requests asserted: they must be ignored.
        rst_n = 1'b0; wr_en = 1'b1; rd_en = 1'b1;
        repeat (3) @(negedge clk);
        rst_n = 1'b1; wr_en = 1'b0; rd_en = 1'b0;

        cycles(1'b0, 1'b1, 2);    // read while empty
        cycles(1'b1, 1'b1, 1);    // write and read together when empty
        cycles(1'b1, 1'b0, 10);   // fill to full, then write while full
        cycles(1'b1, 1'b1, 3);    // write and read together when full, then in between
        cycles(1'b0, 1'b1, 12);   // drain to empty, then read while empty
        cycles(1'b1, 1'b0, 3);
        cycles(1'b1, 1'b1, 4);    // write and read together in between

        random_phase(8'd200, 8'd120, 400);  // write-heavy
        random_phase(8'd120, 8'd200, 400);  // read-heavy
        random_phase(8'd160, 8'd160, 800);  // balanced, pointer wrap

        // Reset during traffic, with the FIFOs non-empty.
        cycles(1'b1, 1'b0, 3);
        @(negedge clk); rst_n = 1'b0; wr_en = 1'b1; rd_en = 1'b1;
        @(negedge clk);
        @(negedge clk); rst_n = 1'b1; wr_en = 1'b0; rd_en = 1'b0;

        random_phase(8'd180, 8'd150, 500);
        cycles(1'b0, 1'b1, 12);   // drain
        cycles(1'b0, 1'b0, 2);

        @(negedge clk); done = 1'b1;
        @(negedge clk);
        @(negedge clk);
        #1;

        passed = pass_a + pass_b;
        failed = fail_a + fail_b;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = "unset";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
